WITH cleaned AS (SELECT *, LEAST(age, credit_limit) AS least_age_credit_limit, INITCAP(TRIM(country)) AS country_title FROM customers WHERE signup_date >= TO_DATE('2023-09-09') AND city = 'Chiang Mai') SELECT id, name, email, country, city, segment, signup_date, is_active, credit_limit, age, least_age_credit_limit, country_title, ROUND(age / SUM(age) OVER (PARTITION BY city), 4) AS age_share, CORR(age, credit_limit) OVER (PARTITION BY segment) AS corr_age_credit_limit, ROUND(credit_limit / SUM(credit_limit) OVER (PARTITION BY city, country), 4) AS credit_limit_share, LEAD(age, 1) OVER w_ordered AS next_age FROM cleaned WINDOW w_ordered AS (PARTITION BY country ORDER BY age, id);
